export const PROJECTS_SCHEMA_SQL = "CREATE TABLE member_version_skill (      -- [P2] 技能绑定在不可变的配置版本上\n  member_version_id TEXT NOT NULL REFERENCES member_version(id),\n  skill_id          TEXT NOT NULL REFERENCES kb_skill(id),\n  skill_version_id  TEXT NOT NULL REFERENCES kb_skill_version(id),\n  PRIMARY KEY (member_version_id, skill_id)\n);\n\nCREATE TABLE project_phase (             -- [P2]\n  id                TEXT PRIMARY KEY,\n  project_id        TEXT NOT NULL REFERENCES project(id),\n  seq               INTEGER NOT NULL,\n  name              TEXT NOT NULL,\n  starts_at         INTEGER NOT NULL,\n  ends_at           INTEGER NOT NULL,\n  status            TEXT NOT NULL DEFAULT 'planned'\n                    CHECK (status IN ('planned','active','awaiting_confirm','done')),\n  confirmer_id      TEXT REFERENCES member(id),\n  confirmed_by      TEXT REFERENCES member(id),\n  confirmed_at      INTEGER,\n  UNIQUE (project_id, seq),\n  CHECK ((status = 'done') = (confirmed_by IS NOT NULL))\n);\n\nCREATE TABLE project_phase_target (      -- [P2]\n  id                TEXT PRIMARY KEY,\n  phase_id          TEXT NOT NULL REFERENCES project_phase(id),\n  metric_id         TEXT REFERENCES project_metric(id),\n  description       TEXT NOT NULL,\n  target_value      REAL,\n  verifier_human_id TEXT NOT NULL REFERENCES member(id)\n);\n\nCREATE TABLE project_phase_check (       -- [P2] 勾选只是记录\n  id                TEXT PRIMARY KEY,\n  phase_id          TEXT NOT NULL REFERENCES project_phase(id),\n  label             TEXT NOT NULL,\n  checked           INTEGER NOT NULL DEFAULT 0,\n  checked_by        TEXT REFERENCES member(id),\n  checked_at        INTEGER\n);\n\nCREATE TABLE project_review (            -- [P2]\n  id                TEXT PRIMARY KEY,\n  project_id        TEXT NOT NULL REFERENCES project(id),\n  kind              TEXT NOT NULL CHECK (kind IN ('weekly','monthly','quarterly','phase')),\n  period_start      INTEGER NOT NULL,\n  period_end        INTEGER NOT NULL,\n  target_version_id TEXT NOT NULL REFERENCES project_target_version(id),\n  status            TEXT NOT NULL DEFAULT 'draft'\n                    CHECK (status IN ('draft','awaiting_confirm','confirmed')),\n  conclusion_text   TEXT,\n  confirmer_id      TEXT REFERENCES member(id),\n  confirmed_by      TEXT REFERENCES member(id),\n  confirmed_at      INTEGER,\n  UNIQUE (project_id, kind, period_start),\n  CHECK ((status = 'confirmed') = (confirmed_by IS NOT NULL))\n);\n\nCREATE TABLE project_review_metric (     -- [P2] 复盘冻结快照；缺数只能是 unknown\n  review_id         TEXT NOT NULL REFERENCES project_review(id),\n  metric_id         TEXT NOT NULL REFERENCES project_metric(id),\n  target_value      REAL,\n  actual_value      REAL,\n  verdict           TEXT NOT NULL CHECK (verdict IN ('met','missed','unknown')),\n  evidence_ref      TEXT,\n  PRIMARY KEY (review_id, metric_id),\n  CHECK (actual_value IS NOT NULL OR verdict = 'unknown')\n);\n\nCREATE TABLE activity_daily (            -- [P2] 热力图日聚合，只由 rollup 作业幂等重算\n  member_id         TEXT NOT NULL REFERENCES member(id),\n  date              TEXT NOT NULL,\n  runs              INTEGER NOT NULL DEFAULT 0,\n  succeeded         INTEGER NOT NULL DEFAULT 0,\n  failed            INTEGER NOT NULL DEFAULT 0,\n  PRIMARY KEY (member_id, date)\n);\n\nCREATE TRIGGER trg_review_metric_unknown BEFORE INSERT ON project_review_metric\nWHEN NEW.verdict <> 'unknown' AND EXISTS (\n  SELECT 1 FROM project_metric m WHERE m.id = NEW.metric_id\n     AND (m.calculator_key IS NULL OR m.source_kind IS NULL))\nBEGIN SELECT RAISE(ABORT, 'DATA_STALE: metric without calculator or source can only be unknown'); END;\n"
